/* eslint-disable max-len */

'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var min = require( '@stdlib/math/base/special/min' );
var ln = require( '@stdlib/math/base/special/ln' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var cos = require( '@stdlib/math/base/special/cos' );
var dlaruv = require( '@stdlib/lapack/base/dlaruv' ).ndarray;


// VARIABLES //

var LV = 128;
var TWOPI = 6.28318530717958647692528676655900576839;


// MAIN //

/**
* Returns a vector of `n` random real numbers from a uniform or normal distribution using alternative indexing semantics.
*
* @param {integer} idist - distribution type: 1=uniform(0,1), 2=uniform(-1,1), 3=normal(0,1)
* @param {Int32Array} iseed - seed array of four integers
* @param {integer} strideIseed - stride length for `iseed`
* @param {NonNegativeInteger} offsetIseed - starting index for `iseed`
* @param {NonNegativeInteger} n - number of random numbers to generate
* @param {Float64Array} x - output array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @returns {Float64Array} output array
*
* @example
* var Int32Array = require( '@stdlib/array/int32' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* var iseed = new Int32Array( [ 0, 1, 2, 3 ] );
* var x = new Float64Array( 5 );
*
* dlarnv( 1, iseed, 1, 0, 5, x, 1, 0 );
* // x => <Float64Array>
*/
function dlarnv( idist, iseed, strideIseed, offsetIseed, n, x, strideX, offsetX ) {
	var il2;
	var il;
	var iv;
	var ox;
	var u;
	var i;

	if ( n <= 0 ) {
		return x;
	}

	u = new Float64Array( LV );
	ox = offsetX;
	for ( iv = 0; iv < n; iv += LV / 2 ) {
		il = min( LV / 2, n - iv );

		// For normal distribution, we need twice as many uniform numbers (Box-Muller):
		if ( idist === 3 ) {
			il2 = 2 * il;
		} else {
			il2 = il;
		}

		// Generate il2 uniform (0,1) numbers:
		dlaruv( il2, iseed, strideIseed, offsetIseed, u, 1, 0 );

		if ( idist === 1 ) {
			// Uniform (0,1): just copy
			for ( i = 0; i < il; i++ ) {
				x[ ox ] = u[ i ];
				ox += strideX;
			}
		} else if ( idist === 2 ) {
			// Uniform (-1,1): transform
			for ( i = 0; i < il; i++ ) {
				x[ ox ] = ( 2.0 * u[ i ] ) - 1.0;
				ox += strideX;
			}
		} else if ( idist === 3 ) {
			// Normal (0,1): Box-Muller transform
			for ( i = 0; i < il; i++ ) {
				x[ ox ] = sqrt( -2.0 * ln( u[ 2 * i ] ) ) * cos( TWOPI * u[ ( 2 * i ) + 1 ] );
				ox += strideX;
			}
		}
	}
	return x;
}


// EXPORTS //

module.exports = dlarnv;
